public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and JScrollPane cannot be null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index is out of bounds");
    }

    table.setRowSelectionInterval(row, row);
    Rectangle cellRect = table.getCellRect(row, 0, true);
    pane.getViewport().scrollRectToVisible(cellRect);

    // Delayed repaint to ensure the table properly paints the newly selected row
    table.repaint(cellRect);
}

