private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    try {
        if (descriptor.startsWith("(")) {
            // It's a method descriptor, extract the argument types
            int end = descriptor.indexOf(')');
            if (end == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
            }
            String argumentTypes = descriptor.substring(1, end);
            int index = 0;
            while (index < argumentTypes.length()) {
                char type = argumentTypes.charAt(index);
                switch (type) {
                    case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                        // These are all single-word types
                        index++;
                        break;
                    case 'D': case 'J':
                        // These are double-word types
                        index += 2;
                        break;
                    case 'L':
                        // Object type, skip until ';'
                        index = argumentTypes.indexOf(';', index) + 1;
                        if (index == 0) {
                            throw new IllegalArgumentException("Invalid object type in descriptor");
                        }
                        break;
                    case '[':
                        // Array type, skip to the end of the array descriptor
                        do {
                            index++;
                        } while (index < argumentTypes.length() && argumentTypes.charAt(index) == '[');
                        if (index == argumentTypes.length()) {
                            throw new IllegalArgumentException("Invalid array descriptor");
                        }
                        // Now we should have a type descriptor for the array element
                        char arrayType = argumentTypes.charAt(index);
                        if (arrayType == 'L') {
                            // Object type, skip until ';'
                            index = argumentTypes.indexOf(';', index) + 1;
                            if (index == 0) {
                                throw new IllegalArgumentException("Invalid object type in array descriptor");
                            }
                        } else {
                            index++;
                        }
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid type character in descriptor: " + type);
                }
            }
        } else {
            // It's a field descriptor, pop based on the type
            switch (descriptor.charAt(0)) {
                case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                    // Single-word types
                    break;
                case 'D': case 'J':
                    // Double-word types
                    break;
                case 'L':
                    // Object type
                    if (descriptor.indexOf(';') == -1) {
                        throw new IllegalArgumentException("Invalid object descriptor: missing ';'");
                    }
                    break;
                case '[':
                    // Array type, no need to do anything special here
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type character in descriptor: " + descriptor.charAt(0));
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

